#!/usr/bin/env node
// drive-bundle.mjs - the whole pipeline's state as one line of text, so nothing the
// agenda knows lives only on this laptop.
//
// Everything else in this repo pushes DERIVED data to Drive: the payload the page
// reads is a rendering, and a rendering cannot be turned back into the files that
// produced it. If the SSD dies at 03:00 the user loses the study log, the overrides,
// the completions, the block edits and the plan - months of accumulated user
// opinion that no scrape can rebuild, because Brightspace never knew any of it.
// This script exists so that after every heavy run there is a complete, plain-text,
// re-importable copy of that state sitting in Drive next to the payload.
//
// ---------------------------------------------------------------------------
// THE ENVELOPE
//
//   AGM2.<crc32>.<base64(gzip(JSON))>.END
//
//   {"v":1, "packedAt":"ISO",
//    "files": {"config.json":"<utf8 content>", "data/latest.json":"...", ...}}
//
// One line, one marker pair, base64 in the middle - the same wire format the rest
// of the pipeline speaks (src/lib/envelope.mjs), because a Google Doc mangles
// anything that looks like formatting and does not mangle this. The mirror is
// compressed for the same reason the payload is: an agent has to TYPE these bytes
// into a document, so their number is a real budget rather than a nicety. The
// CRC32 is over the gzip bytes before base64, so a truncated transcription is
// refused up front instead of failing somewhere deep inside a decompressor.
//
// A scheduled run puts the file's exact contents into a document titled
// `<namespace>-mirror` and trashes every older document of that exact title.
//
// ---------------------------------------------------------------------------
// WHAT GOES IN, AND WHY THE LIST IS A LIST AND NOT A GLOB
//
//   IN   config.json                 the user's tuning: difficulty, schedule, budget
//        data/*.json                 every piece of state the pipeline accumulates
//        data/focus-note.txt         the one non-JSON file that holds user words
//
//   OUT  data/content-dump.json      a scrape artefact - big, and re-fetchable
//        data/sample-*.json          fixtures that live in the repo already
//        data/runlog*                a diary of runs, not state; restoring it would
//                                    overwrite the record of the restore itself
//        data/payload.b64.txt        a rendering; `node src/render.mjs` rebuilds it
//        data/backup.b64.txt         this script's own output, obviously
//        fixtures/                   the bundled sample term is in the repository
//                                    already; mirroring it would be backing up a
//                                    file to the place it came from
//        subdirectories              downloaded course files are materials, not
//                                    state; they are big, they are binary, and they
//                                    belong to their own folder's backup story
//
// The rule that keeps this honest: a file belongs in the mirror when losing it would
// lose something the USER said or the pipeline LEARNED, and not when it can be
// regenerated by running something.
//
// A mirror that is too big to push is a mirror that silently stops happening, so
// there is a hard cap - `drive.maxMirrorChars`, 20,000 characters by default. Over
// it, the Drive copy is skipped with exit 3 and the biggest contributors named; the
// caller logs a skip and the run carries on, because the mirror is insurance and
// insurance never fails the thing it insures.
//
// ---------------------------------------------------------------------------
// THE LOCAL BACKUP HAPPENS FIRST, ALWAYS
//
// `--pack` writes `backups/mirror-<stamp>.txt` before it looks at the cap, before
// it writes the Drive copy, and whether or not either of those succeeds. Insurance
// that depends on an upload is not insurance: the upload is the step most likely to
// be the thing that failed. The newest 14 are kept and the rest deleted, so the
// folder is a fortnight of undo rather than an unbounded pile.
//
// ---------------------------------------------------------------------------
// RESTORE IS DELIBERATELY AWKWARD
//
// `--restore <file>` unpacks into `data/restore-<yyyymmdd-hhmmss>/`, preserving the
// relative paths, and touches nothing live. That is the default because the usual
// reason to restore is "what did the study log say last Tuesday", not "put it all
// back", and because a restore that overwrites by default is a restore that will one
// day overwrite good data with a stale mirror.
//
// `--force` overwrites the live files, and even then it copies each one to
// `<name>.pre-restore.bak` first. Two doors, both of which you have to mean.
//
// Path keys out of the envelope are validated before anything is written: no
// absolute paths, no `..`, no backslashes. The envelope arrives from a Google Doc,
// and a Google Doc is something anyone with the link could have edited.
//
// ---------------------------------------------------------------------------
// CLI
//   node src/drive-bundle.mjs --pack                     write data/backup.b64.txt
//   node src/drive-bundle.mjs --pack --out <file>        ...somewhere else
//   node src/drive-bundle.mjs --restore <file>           unpack to data/restore-<stamp>/
//   node src/drive-bundle.mjs --restore <file> --force   ...and overwrite the live files
//   node src/drive-bundle.mjs --pack --root <dir>        point the whole thing elsewhere
//   node src/drive-bundle.mjs --pack --data <dir>        just the data directory
//   node src/drive-bundle.mjs --pack --config <path>     read another config
//
// Exit codes:
//   0  packed or restored; the summary line says what
//   1  error: unreadable input, a broken envelope, a write that failed
//   2  usage error
//   3  the bundle is over the mirror cap - the DRIVE copy was not written, and the
//      caller is expected to log a skip rather than fail its run. The local backup
//      was still written.

import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { EnvelopeError, budgetOf, pack as packEnvelope, unpack } from "./lib/envelope.mjs";
import { ConfigError, derive, loadConfig } from "./lib/config.mjs";
import { configPath, dataDir as resolveDataDir, repoRoot } from "./lib/paths.mjs";

// --------------------------------------------------------------- constants

export const BUNDLE_VERSION = 1;
export const MARK_HEAD = "AGM";
export const MARK_TAIL = ".END";
export const BACKUP_NAME = "backup.b64.txt";
/** The default from config.drive.maxMirrorChars; characters, not bytes. */
export const DEFAULT_MIRROR_CHARS = 20000;
/** Where the local copies go, and how many of them survive. */
export const BACKUP_DIR = "backups";
export const BACKUP_KEEP = 14;
export const BAK_SUFFIX = ".pre-restore.bak";
export const ROOT_FILES = ["config.json"];
export const DATA_EXTRA_FILES = ["focus-note.txt"];
/** The bundled sample term ships in the repository; it is never state. */
export const FIXTURES_DIR = "fixtures";
export const EXIT = { ok: 0, error: 1, usage: 2, tooBig: 3 };

const LOG = "[drive-bundle]";

// --------------------------------------------------------------- pure helpers

/**
 * Does this name inside data/ belong in the mirror? PURE, and the single place the
 * include/exclude list lives - the header explains each clause.
 */
export function isMirrored(name) {
  if (typeof name !== "string" || !name) return false;
  if (name.startsWith("runlog")) return false;
  if (name.startsWith("sample-")) return false;
  if (name === "content-dump.json") return false;
  if (name === "payload.b64.txt" || name === BACKUP_NAME) return false;
  if (DATA_EXTRA_FILES.includes(name)) return true;
  return name.endsWith(".json");
}

/**
 * A relative key from an envelope, or null if it is not one. No absolute paths, no
 * drive letters, no `..`, no backslashes, no empty segments. PURE.
 */
export function safeRelPath(rel) {
  if (typeof rel !== "string" || !rel || rel.includes("\\") || rel.startsWith("/")) return null;
  if (/^[A-Za-z]:/.test(rel)) return null;
  const parts = rel.split("/");
  if (parts.some((p) => !p || p === "." || p === "..")) return null;
  return parts.join("/");
}

/** `yyyymmdd-hhmmss` in LOCAL time - the stamp a human reads off a folder name. */
export function stamp(now = new Date()) {
  const p = (n) => String(n).padStart(2, "0");
  return (
    `${now.getFullYear()}${p(now.getMonth() + 1)}${p(now.getDate())}` +
    `-${p(now.getHours())}${p(now.getMinutes())}${p(now.getSeconds())}`
  );
}

/** Bytes as the summary line wants them: whole KB above 1 KB, bytes below. */
export function human(bytes) {
  if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  if (bytes >= 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${bytes} B`;
}

/** Wrap the bundle as the compressed mirror envelope. PURE. */
export function wrap(bundle) {
  return packEnvelope("mirror", bundle);
}

/**
 * Text (a mirror envelope, or the bare JSON of one) -> the bundle, or {error}.
 * Tolerates whatever a Google Doc adds around and inside the line: leading blank
 * lines, a trailing newline, soft wraps. Never throws.
 *
 * The bare-JSON path exists for the human case - somebody has decoded a mirror by
 * hand, or is testing with an object - and it is why this is a `{bundle|error}`
 * function rather than a direct call to unpack().
 */
export function unwrap(text) {
  const raw = String(text ?? "").trim();
  if (!raw) return { error: "the file is empty" };

  let bundle;
  if (raw.startsWith("{")) {
    try {
      bundle = JSON.parse(raw);
    } catch (e) {
      return { error: `the payload is not JSON: ${e.message}` };
    }
  } else {
    try {
      const envelope = unpack(raw);
      if (envelope.kind !== "mirror") {
        return { error: `this is a "${envelope.kind}" envelope, not a state mirror - the mirror is ${MARK_HEAD}` };
      }
      bundle = envelope.data;
    } catch (e) {
      if (e instanceof EnvelopeError) return { error: e.message };
      return { error: String(e && e.message ? e.message : e) };
    }
  }

  if (!bundle || typeof bundle !== "object" || Array.isArray(bundle)) return { error: "the payload is not an object" };
  if (bundle.v !== BUNDLE_VERSION) return { error: `unsupported bundle version ${JSON.stringify(bundle.v)}` };
  if (!bundle.files || typeof bundle.files !== "object" || Array.isArray(bundle.files)) {
    return { error: "the bundle has no `files` map" };
  }
  return { bundle };
}

// ------------------------------------------------------------------- reading

/**
 * The relative paths this repo would mirror, in a stable order: config.json first,
 * then data/ alphabetically. Missing files and a missing data/ are normal, not
 * errors - a fresh clone has neither.
 */
export function mirrorPaths(root, dataDir) {
  const out = [];
  for (const name of ROOT_FILES) {
    // Belt and braces: the root list is short and hand-written, but a future
    // addition under fixtures/ would be backing a file up to where it came from.
    if (name.startsWith(`${FIXTURES_DIR}/`) || name === FIXTURES_DIR) continue;
    if (fs.existsSync(path.join(root, name)) && fs.statSync(path.join(root, name)).isFile()) out.push(name);
  }
  let entries = [];
  try {
    entries = fs.readdirSync(dataDir, { withFileTypes: true });
  } catch {
    return out;
  }
  const names = entries
    .filter((e) => e.isFile() && isMirrored(e.name))
    .map((e) => e.name)
    .sort();
  for (const name of names) out.push(`data/${name}`);
  return out;
}

/** Where a relative key lives on this machine. data/ follows --data, the rest --root. */
export function resolveRel(rel, root, dataDir) {
  const parts = rel.split("/");
  if (parts[0] === "data") return path.join(dataDir, ...parts.slice(1));
  return path.join(root, ...parts);
}

/**
 * Read every mirrored file. Returns {files, bytes, sizes}. A file that vanishes
 * between the listing and the read is skipped, not fatal: a heavy run is writing to
 * this directory while the mirror is being taken.
 */
export function collect(root, dataDir) {
  const files = {};
  const sizes = [];
  let bytes = 0;
  for (const rel of mirrorPaths(root, dataDir)) {
    let content;
    try {
      content = fs.readFileSync(resolveRel(rel, root, dataDir), "utf8");
    } catch {
      continue;
    }
    files[rel] = content;
    const size = Buffer.byteLength(content, "utf8");
    sizes.push({ rel, size });
    bytes += size;
  }
  sizes.sort((a, b) => b.size - a.size || (a.rel < b.rel ? -1 : 1));
  return { files, bytes, sizes };
}

// ---------------------------------------------------------------------- pack

/** A filename-safe instant: `mirror-2026-09-01T13-15-00.txt`. PURE. */
export function backupName(now = new Date()) {
  return `mirror-${now.toISOString().replace(/\.\d+Z$/, "").replace(/:/g, "-")}.txt`;
}

/**
 * Write the local copy and prune the folder to the newest BACKUP_KEEP.
 *
 * Returns {file, kept, error}. An error here is REPORTED but never fatal: a
 * machine whose backups/ cannot be written still deserves its Drive mirror.
 * Sorting is by filename, which is why the stamp is ISO - lexical order and
 * chronological order are the same thing.
 */
export function writeLocalBackup(dir, envelope, now = new Date(), keep = BACKUP_KEEP) {
  const file = path.join(dir, backupName(now));
  try {
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(file, envelope);
  } catch (e) {
    return { file: null, kept: 0, error: e.message };
  }
  let names = [];
  try {
    names = fs
      .readdirSync(dir, { withFileTypes: true })
      .filter((e) => e.isFile() && /^mirror-.*\.txt$/.test(e.name))
      .map((e) => e.name)
      .sort();
  } catch {
    return { file, kept: 1, error: null };
  }
  for (const stale of names.slice(0, Math.max(0, names.length - keep))) {
    try {
      fs.rmSync(path.join(dir, stale));
    } catch {
      /* a backup we cannot delete is clutter, not a failure */
    }
  }
  return { file, kept: Math.min(names.length, keep), error: null };
}

/**
 * Build the envelope, save the local copy, then write the Drive copy. Returns
 * {code, line} - the caller prints, so this stays testable without capturing
 * stdout.
 *
 * The order is the point. The local backup is written FIRST and unconditionally:
 * it is the copy that does not depend on a cap, on a write to data/, or on an
 * upload that has not happened yet.
 */
export function pack({
  root,
  dataDir,
  out,
  now = new Date(),
  maxChars = DEFAULT_MIRROR_CHARS,
  backupDir = null,
  docTitle = null,
}) {
  const { files, bytes, sizes } = collect(root, dataDir);
  const count = Object.keys(files).length;
  const envelope = wrap({ v: BUNDLE_VERSION, packedAt: now.toISOString(), files });
  const encoded = envelope.length;

  const backup = writeLocalBackup(backupDir ?? path.join(root, BACKUP_DIR), envelope, now);
  const backupNote = backup.error
    ? ` backup=FAILED(${backup.error})`
    : ` backup=${path.basename(backup.file)} (${backup.kept} kept)`;

  if (encoded > maxChars) {
    const biggest = sizes.slice(0, 5).map((s) => `${s.rel} ${human(s.size)}`).join(", ");
    return {
      code: EXIT.tooBig,
      line:
        `${LOG} pack TOO BIG: encoded=${encoded} chars over the ${maxChars}-char mirror cap ` +
        `(files=${count} bytes=${bytes}); no Drive copy written.${backupNote} biggest: ${biggest}`,
    };
  }

  try {
    fs.mkdirSync(path.dirname(out), { recursive: true });
    fs.writeFileSync(out, envelope);
  } catch (e) {
    return { code: EXIT.error, line: `${LOG} pack FAILED: cannot write ${out}: ${e.message}.${backupNote}` };
  }
  return {
    code: EXIT.ok,
    line:
      `${LOG} pack ok files=${count} bytes=${bytes} encoded=${encoded} out=${out}${backupNote}` +
      (docTitle ? ` doc=${docTitle}` : ""),
  };
}

// ------------------------------------------------------------------- restore

/**
 * Unpack an envelope. Always into `<dataDir>/restore-<stamp>/`; additionally over the
 * live files when `force`, and only after a `.pre-restore.bak` copy of each.
 */
export function restore({ file, root, dataDir, force = false, now = new Date() }) {
  let text;
  try {
    text = fs.readFileSync(file, "utf8");
  } catch (e) {
    return { code: EXIT.error, line: `${LOG} restore FAILED: cannot read ${file}: ${e.message}` };
  }
  const { bundle, error } = unwrap(text);
  if (error) return { code: EXIT.error, line: `${LOG} restore FAILED: ${error}` };

  const entries = [];
  for (const [rel, content] of Object.entries(bundle.files)) {
    const safe = safeRelPath(rel);
    if (!safe) return { code: EXIT.error, line: `${LOG} restore FAILED: refusing the path "${rel}" in the bundle` };
    if (typeof content !== "string") {
      return { code: EXIT.error, line: `${LOG} restore FAILED: "${rel}" is not text` };
    }
    entries.push([safe, content]);
  }
  entries.sort((a, b) => (a[0] < b[0] ? -1 : 1));

  const dir = path.join(dataDir, `restore-${stamp(now)}`);
  let bytes = 0;
  let forced = 0;
  try {
    fs.mkdirSync(dir, { recursive: true });
    for (const [rel, content] of entries) {
      const target = path.join(dir, ...rel.split("/"));
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, content);
      bytes += Buffer.byteLength(content, "utf8");

      if (!force) continue;
      const live = resolveRel(rel, root, dataDir);
      fs.mkdirSync(path.dirname(live), { recursive: true });
      if (fs.existsSync(live)) fs.copyFileSync(live, live + BAK_SUFFIX);
      fs.writeFileSync(live, content);
      forced += 1;
    }
  } catch (e) {
    return { code: EXIT.error, line: `${LOG} restore FAILED: ${e.message}` };
  }

  const packedAt = typeof bundle.packedAt === "string" ? bundle.packedAt : "unknown";
  return {
    code: EXIT.ok,
    line:
      `${LOG} restore ok files=${entries.length} bytes=${bytes} dir=${dir} ` +
      `forced=${forced}${force ? ` (${BAK_SUFFIX} kept)` : ""} packedAt=${packedAt}`,
  };
}

// --------------------------------------------------------------------- CLI

const ROOT = repoRoot();

const USAGE =
  "usage: node src/drive-bundle.mjs --pack [--out <file>] [--root <dir>] [--data <dir>] [--config <path>]\n" +
  "       node src/drive-bundle.mjs --restore <file> [--force] [--root <dir>] [--data <dir>]";

/**
 * The mirror cap, from config, with the default when there is no config to read.
 * A config that will not parse must not cost the user their backup, so the
 * failure is a default rather than an exit.
 */
export function mirrorSettings(argv, root) {
  try {
    const cfg = loadConfig(configPath(argv, root), { warn: () => {} });
    return { maxChars: budgetOf(cfg, "mirror"), docTitle: derive(cfg).docTitles.mirror };
  } catch (e) {
    if (!(e instanceof ConfigError)) throw e;
    return { maxChars: DEFAULT_MIRROR_CHARS, docTitle: null };
  }
}

export function cliMain(argv, opts = {}) {
  const now = opts.now ?? new Date();
  const value = (flag) => {
    const i = argv.indexOf(flag);
    if (i === -1) return null;
    const v = argv[i + 1];
    return v && !v.startsWith("--") ? v : null;
  };

  const wantsPack = argv.includes("--pack");
  const restoreAt = argv.indexOf("--restore");
  const root = value("--root") ?? ROOT;
  const dataDir = value("--data") ?? resolveDataDir(argv, root);

  if (wantsPack === (restoreAt !== -1)) {
    console.log(USAGE);
    return EXIT.usage;
  }

  if (wantsPack) {
    const out = value("--out") ?? path.join(dataDir, BACKUP_NAME);
    const settings = mirrorSettings(argv, root);
    const { code, line } = pack({
      root,
      dataDir,
      out,
      now,
      maxChars: opts.maxChars ?? settings.maxChars,
      docTitle: settings.docTitle,
    });
    console.log(line);
    return code;
  }

  const file = value("--restore");
  if (!file) {
    console.log(USAGE);
    return EXIT.usage;
  }
  const { code, line } = restore({ file, root, dataDir, force: argv.includes("--force"), now });
  console.log(line);
  return code;
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  process.exit(cliMain(process.argv.slice(2)));
}
